INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template) VALUES
  (42, 1, '절대 경로와 상대 경로 구분하기', '지금 위치(현재 디렉터리)가 `/home/kim` 입니다. `/etc/hosts` 와 `docs/memo.txt` 는 각각 어떤 경로일까요?', '경로가 `/` 로 시작하면 어디서든 같은 곳을 가리키는 절대 경로이고, 아니면 지금 위치에서부터 따라가는 상대 경로입니다.', NULL, NULL, '[]', 'choice', '["둘 다 절대 경로다", "`/etc/hosts` 는 절대 경로(맨 앞이 `/`), `docs/memo.txt` 는 상대 경로(현재 위치 `/home/kim` 기준)다", "`/etc/hosts` 는 상대 경로, `docs/memo.txt` 는 절대 경로다", "둘 다 상대 경로다"]', 1, '`/` 로 시작하는 `/etc/hosts` 는 루트부터 시작하는 **절대 경로**라서 어디서 실행해도 같은 파일입니다. `docs/memo.txt` 는 현재 위치 기준이라 `/home/kim/docs/memo.txt` 를 가리키는 **상대 경로**입니다.', NULL, NULL),
  (42, 2, '숨김 파일까지 자세히 보는 ls 옵션 채우기', '`/home/kim` 의 파일을 **숨김 파일(이름이 `.` 으로 시작하는 파일)까지 포함해서 자세히** 보려고 합니다. 명령의 빈칸을 채우세요.', '`-l` 은 자세히(권한·크기·날짜), `-a` 는 숨김 파일 포함입니다. 옵션은 붙여 쓸 수 있습니다.', NULL, NULL, '[]', 'fill', '["-l", "-a", "-la", "-R"]', NULL, '`-l` 은 권한·소유자·크기·날짜를 자세히 보여 주고, `-a` 는 `.` 으로 시작하는 숨김 파일까지 보여 줍니다. 둘을 붙여 `-la` 로 쓰면 둘 다 적용됩니다. `-R` 은 하위 디렉터리까지 재귀로 보는 옵션입니다.', '[2]', 'ls {0} /home/kim'),
  (42, 3, 'ls -l 결과에서 그룹 권한 읽기', '`ls -l` 결과에 `-rwxr-xr--  1 kim dev  120  app.sh` 가 보입니다. 이 파일의 소유자는 `kim`, 그룹은 `dev` 입니다. `dev` 그룹에 속한 **다른 사용자**는 이 파일로 무엇을 할 수 있을까요?', '권한 9칸은 소유자, 그룹, 그 밖의 사람 순서로 세 칸씩 끊어 읽습니다: `rwx` `r-x` `r--`. `r` 읽기, `w` 쓰기, `x` 실행, `-` 없음.', NULL, NULL, '[]', 'choice', '["읽고 실행할 수 있지만 수정(쓰기)은 못 한다", "읽고 쓰고 실행할 수 있다", "읽기만 할 수 있다", "아무것도 못 한다"]', 0, '권한은 `rwx`(소유자) `r-x`(그룹) `r--`(그 밖의 사람)입니다. 그룹은 `r-x` 라서 읽기와 실행은 되지만 쓰기(`w`)는 없습니다. 그 밖의 사람은 `r--` 라서 읽기만 됩니다.', NULL, NULL),
  (42, 4, '새 파일을 만들고 쓰고 확인하고 지우는 순서대로 놓기', '`notes.txt` 라는 파일을 다루는 명령들이 섞여 있습니다. **자연스러운 작업 순서**대로 놓으세요.', '파일이 있어야 쓸 수 있고, 써야 확인할 내용이 있고, 다 쓴 뒤에 지웁니다.', NULL, NULL, '[]', 'order', '["`rm notes.txt` 로 파일 지우기", "`cat notes.txt` 로 내용 확인하기", "`touch notes.txt` 로 빈 파일 만들기", "`echo hello > notes.txt` 로 내용 쓰기"]', NULL, '`touch` 로 빈 파일을 만들고, `echo ... >` 로 내용을 쓰고, `cat` 으로 확인한 뒤, 필요 없으면 `rm` 으로 지웁니다. (`echo ... >` 는 파일이 없으면 스스로 만들기도 하지만, 순서를 익히기 위한 흐름입니다.)', '[2, 3, 1, 0]', NULL),
  (42, 5, 'kill 의 기본 신호 알기', '`kill 1234` 처럼 **신호 종류를 적지 않고** 프로세스를 종료시키려 하면, 기본으로 보내는 신호는 무엇일까요?', '기본 신호는 "정리할 시간을 주고 정상 종료해 달라"는 요청입니다. 강제로 죽이는 신호는 `-9` 를 따로 적어야 합니다.', NULL, NULL, '[]', 'choice', '["`SIGKILL`(9), 즉시 강제로 죽인다", "`SIGTERM`(15), 프로세스에게 정리하고 정상 종료해 달라고 요청한다", "`SIGSTOP`, 프로세스를 일시 중지한다", "아무 신호도 보내지 않는다"]', 1, '`kill` 의 기본 신호는 `SIGTERM`(15)입니다. 프로세스가 열어 둔 파일을 닫는 등 정리하고 끝낼 기회를 줍니다. 말을 듣지 않을 때만 `kill -9`(SIGKILL)로 강제 종료합니다.', NULL, NULL),
  (42, 6, '/proc 의 파일이 무엇인지 알기', '`/proc` 디렉터리에는 `cpuinfo`, `meminfo` 같은 파일이 있습니다. 이 파일들은 무엇일까요?', '"리눅스는 모든 것을 파일처럼 다룬다"는 말의 대표적인 예입니다.', NULL, NULL, '[]', 'choice', '["디스크에 저장된 일반 텍스트 파일이다", "커널이 지금의 시스템 상태(CPU, 메모리, 프로세스 등)를 파일처럼 보여 주는 가상 파일이다", "설치된 프로그램의 목록이다", "사용자 비밀번호가 담긴 파일이다"]', 1, '`/proc` 은 커널이 만들어 보여 주는 **가상 파일 시스템**입니다. `cat /proc/meminfo` 처럼 읽으면 그 순간의 메모리 상태가 나옵니다. 디스크에 저장된 파일이 아니라서 읽을 때마다 값이 달라질 수 있습니다.', NULL, NULL),
  (42, 7, 'cd ~ 가 이동하는 곳 고르기', '`cd ~` 를 입력하면 어디로 이동할까요?', '`~`(물결표)는 "내 집"을 뜻하는 줄임 표기입니다.', NULL, NULL, '[]', 'choice', '["루트 디렉터리 `/`", "현재 사용자의 홈 디렉터리", "직전에 있던 디렉터리", "부모 디렉터리"]', 1, '`~` 는 현재 사용자의 **홈 디렉터리**를 뜻합니다. `kim` 이라면 `/home/kim` 입니다. 그냥 `cd` 만 써도 홈으로 갑니다. 직전 디렉터리는 `cd -`, 부모 디렉터리는 `cd ..` 입니다.', NULL, NULL);
